"""Escaped, standalone preview. It is an export, never a second live datastore."""

from __future__ import annotations

import html
import json
from pathlib import Path

from career_radar.orchestration import ScanResult


def export_preview(result: ScanResult, directory: Path, *, synthetic: bool) -> Path:
    if not synthetic:
        raise ValueError("DASHBOARD_PREVIEW_IS_SYNTHETIC_ONLY; use export backup for private data")
    directory.mkdir(parents=True, exist_ok=True)
    directory.chmod(0o700)
    scores = {s.job_uid: s for s in result.scores}
    payload = []
    for job in result.jobs:
        score = scores[job.job_uid]
        payload.append(
            {
                **job.model_dump(mode="json"),
                "score": score.model_dump(mode="json"),
                "brief": next((b for b in result.briefs if b["job_uid"] == job.job_uid), None),
            }
        )
    encoded = (
        json.dumps(payload).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    )
    page = TEMPLATE.replace("__JOBS__", encoded).replace(
        "__DATA_MODE__",
        "Synthetic demo · no live jobs" if synthetic else "Private export · snapshot only",
    )
    destination = directory / "dashboard.html"
    destination.write_text(page)
    destination.chmod(0o600)
    email = directory / "email-preview.html"
    email.write_text(
        '<!doctype html><meta charset="utf-8"><title>Owner email preview</title><style>body{font:16px/1.6 system-ui;max-width:850px;margin:50px auto;padding:30px}pre{white-space:pre-wrap}</style><h1>Owner notification preview</h1><p>'
        + ("Synthetic fixture data" if synthetic else "Private snapshot")
        + "</p><pre>"
        + html.escape(result.email_preview)
        + "</pre>"
    )
    email.chmod(0o600)
    summary = directory / "run-summary.json"
    summary.write_text(result.summary.model_dump_json(indent=2))
    summary.chmod(0o600)
    return destination


